#!/usr/bin/env bash
# Install versioned git hooks. Do not hand-edit .git/hooks/pre-commit body.
# Prefer this over copying legacy hook scripts into .git/hooks/.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HOOK_DIR="$ROOT/.git/hooks"
HOOK="$HOOK_DIR/pre-commit"
SRC="$ROOT/scripts/pre-commit-hook.sh"

if [ ! -d "$ROOT/.git" ]; then
  echo "FAIL: not a git worktree at $ROOT" >&2
  exit 1
fi
if [ ! -f "$SRC" ]; then
  echo "FAIL: missing $SRC" >&2
  exit 1
fi

mkdir -p "$HOOK_DIR"
cat > "$HOOK" <<'EOF'
#!/usr/bin/env bash
# AUTO-GENERATED by scripts/install_git_hooks.sh — do not edit.
# Real logic lives in scripts/pre-commit-hook.sh (version-controlled).
set -euo pipefail
ROOT="$(git rev-parse --show-toplevel)"
exec bash "$ROOT/scripts/pre-commit-hook.sh" "$@"
EOF
chmod +x "$HOOK"
echo "OK: installed thin pre-commit → scripts/pre-commit-hook.sh"
echo "    (also invokes pre-commit-engine-guard via the versioned script)"
